    dqsAdd( a, w.x, pivot, real, dual, scale );
    dqsAdd( b, w.y, pivot, real, dual, scale );
    dqsAdd( c, w.z, pivot, real, dual, scale );
    dqsAdd( d, w.w, pivot, real, dual, scale );
